#include <zephyr/data/cobs.h>
#include <errno.h>
#include <string.h>
#include <zephyr/net_buf.h>
#include <zephyr/sys/util.h>

enum _my_cobs_dec_state {
	_MY_DEC_STATE_IDLE = 0,
	_MY_DEC_STATE_DATA,
	_MY_DEC_STATE_END_OF_BLOCK,
};

struct _my_cobs_encoder {
	cobs_stream_cb cb;
	void *user_data;
	uint8_t buf[253];
	uint8_t delim;
	uint8_t trailing;
	uint8_t code;
};

struct _my_cobs_decoder {
	cobs_stream_cb cb;
	void *user_data;
	uint8_t delim;
	uint8_t trailing : 1;
	uint8_t state : 7;
	uint8_t code;
	uint8_t remaining;
};

BUILD_ASSERT(sizeof(struct _my_cobs_encoder) <= sizeof(struct cobs_encoder));
BUILD_ASSERT(sizeof(struct _my_cobs_decoder) <= sizeof(struct cobs_decoder));

int cobs_encoder_init(struct cobs_encoder *enc, cobs_stream_cb cb, void *user_data, uint32_t flags)
{
	struct _my_cobs_encoder *m = (struct _my_cobs_encoder *)enc;

	if (enc == NULL || cb == NULL) {
		return -EINVAL;
	}

	m->cb = cb;
	m->user_data = user_data;
	m->delim = COBS_FLAG_CUSTOM_DELIMITER(flags);
	m->trailing = (flags & COBS_FLAG_TRAILING_DELIMITER) ? 1U : 0U;
	m->code = 1U;

	return 0;
}

int cobs_encoder_write(struct cobs_encoder *enc, const uint8_t *buf, size_t len)
{
	struct _my_cobs_encoder *m = (struct _my_cobs_encoder *)enc;
	uint8_t tmp[255];
	int ret;

	if (enc == NULL || (buf == NULL && len > 0)) {
		return -EINVAL;
	}

	for (size_t i = 0; i < len; i++) {
		uint8_t b = buf[i];

		if (b == 0x00) {
			if (m->code == 0U) {
				m->code = 1U;
			}
			tmp[0] = m->code ^ m->delim;
			if (m->code > 1U) {
				memcpy(&tmp[1], m->buf, m->code - 1U);
			}
			ret = m->cb(tmp, m->code, m->user_data);
			if (ret < 0) {
				return ret;
			}
			m->code = 1U;
		} else {
			if (m->code == 0U) {
				m->code = 1U;
			}
			if (m->code == 254U) {
				tmp[0] = 0xffU ^ m->delim;
				memcpy(&tmp[1], m->buf, 253U);
				tmp[254] = b ^ m->delim;
				ret = m->cb(tmp, 255U, m->user_data);
				if (ret < 0) {
					return ret;
				}
				m->code = 0U;
			} else {
				m->buf[m->code - 1U] = b ^ m->delim;
				m->code++;
			}
		}
	}

	return (int)len;
}

int cobs_encoder_close(struct cobs_encoder *enc)
{
	struct _my_cobs_encoder *m = (struct _my_cobs_encoder *)enc;
	uint8_t tmp[255];
	int ret;

	if (enc == NULL) {
		return -EINVAL;
	}

	if (m->code > 0U) {
		tmp[0] = m->code ^ m->delim;
		if (m->code > 1U) {
			memcpy(&tmp[1], m->buf, m->code - 1U);
		}
		ret = m->cb(tmp, m->code, m->user_data);
		if (ret < 0) {
			m->code = 1U;
			return ret;
		}
	}

	m->code = 1U;

	if (m->trailing) {
		ret = m->cb(&m->delim, 1U, m->user_data);
		if (ret < 0) {
			return ret;
		}
	}

	return 0;
}

int cobs_decoder_init(struct cobs_decoder *dec, cobs_stream_cb cb, void *user_data, uint32_t flags)
{
	struct _my_cobs_decoder *m = (struct _my_cobs_decoder *)dec;

	if (dec == NULL || cb == NULL) {
		return -EINVAL;
	}

	m->cb = cb;
	m->user_data = user_data;
	m->delim = COBS_FLAG_CUSTOM_DELIMITER(flags);
	m->trailing = (flags & COBS_FLAG_TRAILING_DELIMITER) ? 1U : 0U;
	m->state = _MY_DEC_STATE_IDLE;
	m->code = 0U;
	m->remaining = 0U;

	return 0;
}

int cobs_decoder_write(struct cobs_decoder *dec, const uint8_t *buf, size_t len)
{
	struct _my_cobs_decoder *m = (struct _my_cobs_decoder *)dec;
	int ret;

	if (dec == NULL || (buf == NULL && len > 0)) {
		return -EINVAL;
	}

	for (size_t i = 0; i < len; i++) {
		uint8_t b = buf[i];

		if (m->state == _MY_DEC_STATE_DATA) {
			uint8_t val;

			if (b == m->delim) {
				return -EINVAL;
			}
			val = b ^ m->delim;
			ret = m->cb(&val, 1U, m->user_data);
			if (ret < 0) {
				return ret;
			}
			m->remaining--;
			if (m->remaining == 0U) {
				m->state = _MY_DEC_STATE_END_OF_BLOCK;
			}
		} else {
			uint8_t val;

			if (b == m->delim) {
				if (!m->trailing) {
					return -EINVAL;
				}
				m->state = _MY_DEC_STATE_IDLE;
				m->code = 0U;
				m->remaining = 0U;
				ret = m->cb(NULL, 0U, m->user_data);
				if (ret < 0) {
					return ret;
				}
				continue;
			}

			if (m->state == _MY_DEC_STATE_END_OF_BLOCK && m->code < 0xffU) {
				uint8_t zero = 0x00U;

				ret = m->cb(&zero, 1U, m->user_data);
				if (ret < 0) {
					return ret;
				}
			}

			val = b ^ m->delim;
			m->code = val;
			m->remaining = val - 1U;
			m->state = (m->remaining == 0U) ? _MY_DEC_STATE_END_OF_BLOCK
							: _MY_DEC_STATE_DATA;
		}
	}

	return (int)len;
}

int cobs_decoder_close(struct cobs_decoder *dec)
{
	struct _my_cobs_decoder *m = (struct _my_cobs_decoder *)dec;

	if (dec == NULL) {
		return -EINVAL;
	}

	if (m->state == _MY_DEC_STATE_DATA) {
		return -EINVAL;
	}

	m->state = _MY_DEC_STATE_IDLE;
	m->code = 0U;
	m->remaining = 0U;

	return 0;
}

static int _my_cobs_buf_write_cb(const uint8_t *buf, size_t len, void *user_data)
{
	struct net_buf *dst = user_data;

	if (buf == NULL || len == 0U) {
		return 0;
	}

	if (net_buf_tailroom(dst) < len) {
		return -ENOMEM;
	}

	(void)net_buf_add_mem(dst, buf, len);

	return 0;
}

int cobs_encode(struct net_buf *src, struct net_buf *dst, uint32_t flags)
{
	struct cobs_encoder enc;
	int ret;

	if (src == NULL || dst == NULL) {
		return -EINVAL;
	}

	ret = cobs_encoder_init(&enc, _my_cobs_buf_write_cb, dst, flags);
	if (ret < 0) {
		return ret;
	}

	ret = cobs_encoder_write(&enc, src->data, src->len);
	if (ret < 0) {
		return ret;
	}

	net_buf_pull(src, src->len);

	return cobs_encoder_close(&enc);
}

int cobs_decode(struct net_buf *src, struct net_buf *dst, uint32_t flags)
{
	struct cobs_decoder dec;
	int ret;

	if (src == NULL || dst == NULL) {
		return -EINVAL;
	}

	ret = cobs_decoder_init(&dec, _my_cobs_buf_write_cb, dst, flags);
	if (ret < 0) {
		return ret;
	}

	ret = cobs_decoder_write(&dec, src->data, src->len);
	if (ret < 0) {
		return ret;
	}

	net_buf_pull(src, src->len);

	return cobs_decoder_close(&dec);
}

